package com.lolfm.composition;
import java.util.*;
public final class CompositionDeficiencyPolicy{public static final double ENGAGE=.35,FRONTLINE=.35,PEEL=.30,WAVE_CLEAR=.35,OBJECTIVE_DAMAGE=.35,SUSTAINED_DAMAGE=.35,SIDE_LANE=.30,DAMAGE_SKEW=.80;private static final Map<CompositionDeficiency,DeficiencyDefinition>DEFINITIONS=build();private CompositionDeficiencyPolicy(){}public static Map<CompositionDeficiency,DeficiencyDefinition>definitions(){return DEFINITIONS;}private static Map<CompositionDeficiency,DeficiencyDefinition>build(){EnumMap<CompositionDeficiency,DeficiencyDefinition>m=new EnumMap<>(CompositionDeficiency.class);one(m,CompositionDeficiency.NO_RELIABLE_ENGAGE,CompositionCapability.ENGAGE,ENGAGE);one(m,CompositionDeficiency.LOW_FRONTLINE,CompositionCapability.FRONTLINE,FRONTLINE);one(m,CompositionDeficiency.LOW_PEEL,CompositionCapability.PEEL,PEEL);one(m,CompositionDeficiency.LOW_WAVE_CLEAR,CompositionCapability.WAVE_CLEAR,WAVE_CLEAR);one(m,CompositionDeficiency.LOW_OBJECTIVE_DAMAGE,CompositionCapability.OBJECTIVE_DAMAGE,OBJECTIVE_DAMAGE);one(m,CompositionDeficiency.LOW_SUSTAINED_DAMAGE,CompositionCapability.SUSTAINED_DAMAGE,SUSTAINED_DAMAGE);m.put(CompositionDeficiency.NO_SIDE_LANE_ANSWER,new DeficiencyDefinition(CompositionDeficiency.NO_SIDE_LANE_ANSWER,Map.of(CompositionCapability.SIDE_LANE_PRESSURE,SIDE_LANE,CompositionCapability.WAVE_CLEAR,WAVE_CLEAR),key(CompositionDeficiency.NO_SIDE_LANE_ANSWER)));m.put(CompositionDeficiency.DAMAGE_CHANNEL_SKEW,new DeficiencyDefinition(CompositionDeficiency.DAMAGE_CHANNEL_SKEW,Map.of(),key(CompositionDeficiency.DAMAGE_CHANNEL_SKEW)));return Map.copyOf(m);}private static void one(Map<CompositionDeficiency,DeficiencyDefinition>m,CompositionDeficiency d,CompositionCapability c,double t){m.put(d,new DeficiencyDefinition(d,Map.of(c,t),key(d)));}private static String key(CompositionDeficiency d){return "composition.deficiency."+d.name().toLowerCase();}}
